export const speechStandardVoices: SpeechStandardVoice[] = rows.map(row => {
  const [speaker = '', name = '', gender = '', language = '', scenes = '', capabilities = '', notes = '', description = '', sample = '', inference_mode = ''] = row
  return { speaker, name, gender, language, scenes, capabilities, notes, description, inference_mode,
    sample_url: sampleBase + sample,
    group: speaker.startsWith('zh_') || speaker.startsWith('ICL_uranus_zh_') ? '中文与多语种' : '外语' }
})
const bySpeaker = new Map(speechStandardVoices.map(voice => [voice.speaker, voice]))
export const speechStandardVoice = (speaker: string): SpeechStandardVoice | undefined => bySpeaker.get(speaker)

export function speechVoiceMatches(voice: SpeechStandardVoice, search: string): boolean {
  const text = [voice.name, voice.speaker, voice.gender, voice.language, voice.scenes, voice.description].join(' ').toLocaleLowerCase()
  return search.trim().toLocaleLowerCase().split(/\s+/).every(word => text.includes(word))
}
